prog='''def transform(grid):
    import collections
    H, W = len(grid), len(grid[0])
    bg = collections.Counter(v for row in grid for v in row).most_common(1)[0][0]
    # 0 is not a drawable line color (it is the background color in demo 6)
    pts = collections.defaultdict(list)
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v not in (bg, 0):
                pts[v].append((r, c))
    out = [row[:] for row in grid]
    for col, cells in pts.items():
        cset = set(cells)
        best = None
        for d in (1, -1):
            groups = collections.defaultdict(list)
            for p in cells:
                groups[p[1] - d * p[0]].append(p)
            for key, gsegg in groups.items():
                gseg = sorted(gsegg)
                # largest contiguous diagonal run within this diagonal
                runs, cur = [], [gseg[0]]
                for p in gseg[1:]:
                    if p[0] == cur[-1][0] + 1:
                        cur.append(p)
                    else:
                        runs.append(cur); cur = [p]
                runs.append(cur)
                run = max(runs, key=len)
                if len(run) >= 2 and (best is None or len(run) > len(best[0])):
                    best = (run, d)
        if best is None:
            continue
        seg, d = best
        dirs = [(-1, -1) if d == 1 else (-1, +1),
                (+1, +1) if d == 1 else (+1, -1)]
        caps = []
        for (r0, c0), (dr, dc) in zip(seg, dirs):
            rr, cc = r0 + dr, c0 + dc
            cap = False
            while 0 <= rr < H and 0 <= cc < W:
                if out[rr][cc] != bg:
                    cap = True
                    break
                rr += dr; cc += dc
            caps.append(cap)
        if all(caps):
            continue
        if not any(caps):
            ei = 0  # extend the upper end toward decreasing row
        else:
            ei = 1 if caps[0] else 0
        dr, dc = dirs[ei]
        r0, c0 = seg[ei]
        rr, cc = r0 + dr, c0 + dc
        while 0 <= rr < H and 0 <= cc < W:
            if out[rr][cc] != bg:
                break
            out[rr][cc] = col
            rr += dr; cc += dc
    return out
'''
